export async function getProductPage(productId: string) {
  // 1. Critical Call: Must succeed or fail the page
  const product = await catalogService.getProduct(productId);

  // 2. Non-critical calls: Execute concurrently with fallbacks
  const [reviewsResult, recsResult] = await Promise.allSettled([
    reviewService.getReviews(productId),
    recommendationService.getRelatedProducts(productId),
  ]);

  return {
    product,
    reviews: reviewsResult.status === 'fulfilled'
      ? reviewsResult.value
      : { rating: 4.5, count: 120, list: [] }, // Stale default
    recommendations: recsResult.status === 'fulfilled'
      ? recsResult.value
      : [], // Omit gracefully on failure
  };
}
